const crypto = require('crypto');
const env = (name) => $env[name];

function header(headers, name) {
  const match = Object.entries(headers || {}).find(([key]) => key.toLowerCase() === name.toLowerCase());
  return Array.isArray(match?.[1]) ? match[1][0] : match?.[1];
}

function rawBodyFrom(item) {
  const encoded = item.binary?.data?.data;
  if (encoded) return Buffer.from(encoded, 'base64').toString('utf8');
  const body = item.json.body;
  return typeof body === 'string' ? body : JSON.stringify(body || {});
}

function safeCompare(a, b) {
  const left = Buffer.from(String(a || ''));
  const right = Buffer.from(String(b || ''));
  return left.length === right.length && crypto.timingSafeEqual(left, right);
}

function normalizeText(text) {
  return String(text || '').replace(/\r\n/g, '\n').trim();
}

function makeCorrelation(issueKey, eventId, ts) {
  const source = `${issueKey}-${eventId || ts || Date.now()}`;
  return source.toUpperCase().replace(/[^A-Z0-9-]+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '');
}

function makeStandupCorrelation(eventId, ts) {
  const date = new Date();
  const stamp = date.toISOString().replace(/[-:]/g, '').replace(/\..+$/, '').replace('T', '-');
  return makeCorrelation(`STANDUP-${stamp}`, eventId, ts);
}

const item = $input.first();
const headers = item.json.headers || {};
const rawBody = rawBodyFrom(item);
const signingSecret = env('SLACK_SIGNING_SECRET');

if (!signingSecret) {
  throw new Error('SLACK_RECEIVED failed: SLACK_SIGNING_SECRET is not configured');
}

const timestamp = header(headers, 'x-slack-request-timestamp');
const signature = header(headers, 'x-slack-signature');
if (!timestamp || !signature) {
  throw new Error('SLACK_RECEIVED failed: missing Slack signature headers');
}

const requestAgeSeconds = Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp));
if (!Number.isFinite(requestAgeSeconds) || requestAgeSeconds > 60 * 5) {
  throw new Error('SLACK_RECEIVED failed: stale Slack request timestamp');
}

const expectedSignature =
  'v0=' + crypto.createHmac('sha256', signingSecret).update(`v0:${timestamp}:${rawBody}`).digest('hex');
if (!safeCompare(expectedSignature, signature)) {
  throw new Error('SLACK_RECEIVED failed: invalid Slack request signature');
}

const body = typeof item.json.body === 'object' && item.json.body !== null ? item.json.body : JSON.parse(rawBody);

if (body.type === 'url_verification') {
  console.log(JSON.stringify({ stage: 'SLACK_RECEIVED', event: 'url_verification' }));
  return [
    {
      json: {
        ackStatusCode: 200,
        ackText: body.challenge,
        shouldProcess: false,
        ignored: true,
        ignoreReason: 'url_verification',
      },
    },
  ];
}

const event = body.event || {};
const retryNum = header(headers, 'x-slack-retry-num');
const configuredChannelId = env('SLACK_CHANNEL_ID');
const text = normalizeText(event.text);
const issueMatch = text.match(/\bSYSCO-\d+\b/i);
const slackThreadTs = event.thread_ts || event.ts;

const base = {
  ackStatusCode: 200,
  ackText: 'ok',
  slackEventId: body.event_id,
  slackChannelId: event.channel,
  slackMessageTs: event.ts,
  slackThreadTs,
  requesterIdentity: event.user || event.username || '',
};

if (retryNum) {
  console.log(JSON.stringify({ stage: 'SLACK_RECEIVED', ignored: true, reason: 'slack_retry', eventId: body.event_id }));
  return [{ json: { ...base, shouldProcess: false, ignored: true, ignoreReason: 'slack_retry' } }];
}

if (body.type !== 'event_callback' || event.type !== 'message') {
  return [{ json: { ...base, shouldProcess: false, ignored: true, ignoreReason: 'not_message_event' } }];
}

if (event.bot_id || event.subtype === 'bot_message') {
  return [{ json: { ...base, shouldProcess: false, ignored: true, ignoreReason: 'bot_message' } }];
}

if (!configuredChannelId || event.channel !== configuredChannelId) {
  return [{ json: { ...base, shouldProcess: false, ignored: true, ignoreReason: 'wrong_channel' } }];
}

if (!text) {
  return [{ json: { ...base, shouldProcess: false, ignored: true, ignoreReason: 'empty_message' } }];
}

const standupMatch = text.match(/^STANDUP(?:\s+DRY\s+RUN)?\b/i);
if (standupMatch) {
  const dryRun = /^STANDUP\s+DRY\s+RUN\b/i.test(standupMatch[0]);
  const transcript = normalizeText(text.slice(standupMatch[0].length));
  if (!transcript) {
    return [{ json: { ...base, shouldProcess: false, ignored: true, ignoreReason: 'empty_standup_transcript' } }];
  }

  const correlationId = makeStandupCorrelation(body.event_id, event.ts);
  console.log(
    JSON.stringify({
      stage: 'STANDUP_RECEIVED',
      correlationId,
      dryRun,
      slackChannelId: event.channel,
    }),
  );

  return [
    {
      json: {
        ...base,
        shouldProcess: false,
        standupShouldProcess: true,
        ignored: false,
        standupDryRun: dryRun,
        standupTranscript: transcript,
        correlationId,
      },
    },
  ];
}

const staticData = $getWorkflowStaticData('global');
staticData.seenSlackEvents = staticData.seenSlackEvents || {};
const now = Date.now();
for (const [eventId, seenAt] of Object.entries(staticData.seenSlackEvents)) {
  if (now - Number(seenAt) > 24 * 60 * 60 * 1000) delete staticData.seenSlackEvents[eventId];
}
if (body.event_id && staticData.seenSlackEvents[body.event_id]) {
  return [{ json: { ...base, shouldProcess: false, ignored: true, ignoreReason: 'duplicate_event' } }];
}
if (body.event_id) staticData.seenSlackEvents[body.event_id] = now;

const jiraIssueKey = issueMatch ? issueMatch[0].toUpperCase() : '';
const requestedChange = issueMatch ? normalizeText(text.replace(issueMatch[0], '')).replace(/^[-:\s]+/, '') : text;
const jiraIssueKeyProvided = Boolean(jiraIssueKey);
const preliminaryKey = jiraIssueKey || `${env('JIRA_PROJECT_KEY') || 'SYSCO'}-NEW`;
const correlationId = makeCorrelation(preliminaryKey, body.event_id, event.ts);

console.log(JSON.stringify({ stage: 'SLACK_RECEIVED', correlationId, jiraIssueKey, jiraIssueKeyProvided, slackChannelId: event.channel }));

return [
  {
    json: {
      ...base,
      shouldProcess: true,
      ignored: false,
      jiraIssueKey,
      requestedJiraIssueKey: jiraIssueKey,
      originalJiraIssueKey: jiraIssueKey,
      jiraIssueKeyProvided,
      requestedChange,
      correlationId,
    },
  },
];

const env = (name) => $env[name];
const https = require('https');
const http = require('http');

async function httpRequest(url, options = {}) {
  const method = options.method || 'GET';
  const body = options.body || '';
  const headers = { ...(options.headers || {}) };
  if (body && !headers['Content-Length']) headers['Content-Length'] = Buffer.byteLength(body);
  const client = url.startsWith('https:') ? https : http;

  return await new Promise((resolve, reject) => {
    const request = client.request(url, { method, headers }, (response) => {
      const chunks = [];
      response.on('data', (chunk) => chunks.push(Buffer.from(chunk)));
      response.on('end', () => {
        const status = response.statusCode || 0;
        resolve({
          status,
          ok: status >= 200 && status < 300,
          headers: response.headers,
          bodyText: Buffer.concat(chunks).toString('utf8'),
        });
      });
    });
    request.on('error', reject);
    request.setTimeout(30000, () => request.destroy(new Error(`HTTP ${method} ${url} timed out`)));
    if (body) request.write(body);
    request.end();
  });
}

async function postSlack(channel, threadTs, text) {
  if (!env('SLACK_BOT_TOKEN')) return;
  await httpRequest('https://slack.com/api/chat.postMessage', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${env('SLACK_BOT_TOKEN')}`,
      'Content-Type': 'application/json; charset=utf-8',
    },
    body: JSON.stringify({
      channel,
      thread_ts: threadTs,
      unfurl_links: false,
      unfurl_media: false,
      text,
    }),
  });
}

const input = $input.first().json;
if (!input.standupShouldProcess) return [{ json: input }];

try {
  const secret = env('STANDUP_INTERNAL_SECRET') || env('LOCAL_WORKER_SECRET');
  if (!secret) throw new Error('Missing STANDUP_INTERNAL_SECRET or LOCAL_WORKER_SECRET');

  const workflowUrl = env('STANDUP_WORKFLOW_URL') || 'http://127.0.0.1:5678/webhook/poc/standup/jira';
  const response = await httpRequest(workflowUrl, {
    method: 'POST',
    headers: {
      Accept: 'application/json',
      'Content-Type': 'application/json',
      'x-poc-standup-secret': secret,
    },
    body: JSON.stringify({
      correlation_id: input.correlationId,
      dry_run: Boolean(input.standupDryRun),
      transcript: input.standupTranscript,
      slack_channel_id: input.slackChannelId,
      slack_message_ts: input.slackMessageTs,
      slack_thread_ts: input.slackThreadTs,
      requester_identity: input.requesterIdentity || '',
      slack_event_id: input.slackEventId || '',
    }),
  });

  if (!response.ok) {
    throw new Error(`Standup workflow dispatch failed (${response.status}): ${response.bodyText.slice(0, 600)}`);
  }

  console.log(JSON.stringify({ stage: 'STANDUP_RECEIVED', outcome: 'dispatched', correlationId: input.correlationId }));
  return [{ json: { ...input, standupDispatched: true } }];
} catch (error) {
  const message = String(error.message || error).slice(0, 900);
  await postSlack(
    input.slackChannelId,
    input.slackThreadTs,
    `Standup Jira automation failed before analysis.\n\nStage: STANDUP_RECEIVED\nCorrelation: ${input.correlationId}\nError: ${message}`,
  ).catch(() => {});
  return [{ json: { ...input, standupDispatched: false, standupDispatchError: message } }];
}

const env = (name) => $env[name];
const https = require('https');
const http = require('http');

function requiredEnv(names) {
  const missing = names.filter((name) => !env(name));
  if (missing.length) throw new Error(`Missing environment variable(s): ${missing.join(', ')}`);
}

function docParagraphs(lines) {
  return {
    type: 'doc',
    version: 1,
    content: lines.map((line) => ({
      type: 'paragraph',
      content: line ? [{ type: 'text', text: line }] : [],
    })),
  };
}

function adfToText(node) {
  if (!node) return '';
  if (typeof node === 'string') return node;
  if (Array.isArray(node)) return node.map(adfToText).filter(Boolean).join('\n');
  if (node.type === 'text') return node.text || '';
  if (Array.isArray(node.content)) return node.content.map(adfToText).filter(Boolean).join(node.type === 'paragraph' ? ' ' : '\n');
  return '';
}

function chooseActiveTransition(transitions) {
  const candidates = transitions || [];
  const preferred = [/in progress/i, /start/i, /doing/i, /active/i, /selected for development/i];
  return candidates.find((transition) => {
    const label = `${transition.name || ''} ${transition.to?.name || ''}`;
    return preferred.some((pattern) => pattern.test(label));
  });
}

function makeCorrelation(issueKey, eventId, ts) {
  const source = `${issueKey}-${eventId || ts || Date.now()}`;
  return source.toUpperCase().replace(/[^A-Z0-9-]+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '');
}

function summaryFromRequest(requestedChange) {
  const normalized = String(requestedChange || '').replace(/\s+/g, ' ').trim();
  if (!normalized) return 'Prototype request from Slack';
  const summary = normalized.replace(/[.?!]+$/g, '');
  if (summary.length <= 120) return summary;
  return `${summary.slice(0, 117).replace(/\s+\S*$/g, '')}...`;
}

function chooseIssueType(issueTypes) {
  const standard = (issueTypes || []).filter((type) => !type.subtask);
  return (
    standard.find((type) => /^story$/i.test(type.name)) ||
    standard.find((type) => /^task$/i.test(type.name)) ||
    standard.find((type) => /feature/i.test(type.name)) ||
    standard[0] ||
    (issueTypes || [])[0]
  );
}

async function jiraFetch(path, options = {}) {
  const baseUrl = env('JIRA_BASE_URL').replace(/\/$/, '');
  const response = await httpRequest(`${baseUrl}${path}`, {
    ...options,
    headers: {
      Authorization: env('JIRA_AUTH_HEADER'),
      Accept: 'application/json',
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
  });
  const text = response.bodyText;
  let data = {};
  if (text) {
    try {
      data = JSON.parse(text);
    } catch {
      data = { raw: text.slice(0, 600) };
    }
  }
  if (!response.ok) {
    const error = new Error(`Jira ${options.method || 'GET'} ${path} failed (${response.status}): ${text.slice(0, 600)}`);
    error.status = response.status;
    error.path = path;
    error.method = options.method || 'GET';
    error.bodyText = text;
    error.data = data;
    throw error;
  }
  return data;
}

async function createIssueFromSlackRequest(input, requestedJiraIssueKey) {
  const projectKey = env('JIRA_PROJECT_KEY');
  const project = await jiraFetch(`/rest/api/3/project/${encodeURIComponent(projectKey)}`);
  const issueType = chooseIssueType(project.issueTypes);
  if (!issueType?.id) {
    throw new Error(`No usable issue type found for project ${projectKey}`);
  }

  const suppliedKeyLine = requestedJiraIssueKey
    ? `Requested key ${requestedJiraIssueKey} did not exist.`
    : 'No Jira key was provided in the Slack request.';
  const slackRequestText = [requestedJiraIssueKey, input.requestedChange || ''].filter(Boolean).join('\n').trim();
  const created = await jiraFetch('/rest/api/3/issue', {
    method: 'POST',
    body: JSON.stringify({
      fields: {
        project: { key: projectKey },
        issuetype: { id: issueType.id },
        summary: summaryFromRequest(input.requestedChange),
        description: docParagraphs([
          `Created by the Slack prototype automation. ${suppliedKeyLine}`,
          `Slack channel: ${input.slackChannelId}`,
          `Slack message ts: ${input.slackMessageTs}`,
          `Slack thread ts: ${input.slackThreadTs}`,
          `Requester: ${input.requesterIdentity || 'unknown'}`,
          '',
          'Full Slack request:',
          slackRequestText,
        ]),
      },
    }),
  });

  return {
    key: created.key,
    issueTypeName: issueType.name,
  };
}

